def add(photo,area,name,warehouse,steps,branches='',legacy=False):
    id=re.sub('[^a-z0-9]+','-',name.lower()).strip('-')
    assert id not in {x['id'] for x in flows},id
    sid=f'photo-{photo}'
    file='IMG_'+str(photo)+('.jpeg' if photo=='0698' else '.HEIC')
    sources.setdefault(sid,dict(id=sid,file=file,image=f'assets/process-flows/IMG_{photo}.jpg',generation='Legacy overview' if legacy else 'Detailed flow' if photo!='0698' else 'Owner whiteboard',note='IMG_5903 was found in the same supplied folder; it is not in the typed file list.' if photo==5903 else 'Read from the owner-supplied photograph. Small text must be confirmed against the original.'))
    activities=[];actions=[]
    for j,item in enumerate(steps):
        kind,title=item.split(':',1);group=f'{id}-step-{j+1}';activities.append(dict(id=group,sequence=j+1,name=title,kind=kind))
        for k,(verb,skill,caps) in enumerate(recipes[kind]):
            aid=f'{group}-a{k+1}'
            actions.append(dict(id=aid,name=f'{verb} · {title}',taskGroup=title,workElement=verb,skill=skill,requiredCapabilities=caps,seconds=None,frequency=1,payloadKg=None,reachM=None,aisleM=None,dependency=actions[-1]['id'] if actions else '',parallel=False,source='Assumed',sourceId=sid,timingMethod='Not measured',mtmCode='',sampleCount=None,object='Confirm the handled item',recovery='Stop this activity. Keep the load stable. Ask the assigned operator to resolve the fault.',note='Engineering decomposition of the source activity. Confirm the object, handoff, units, and repetition before use.',humanRetained=kind in ['review','secure','door','document'],humanReason='Retain an accountable person for this draft decision or operating permission. This is not a claim that future automation is impossible.' if kind in ['review','secure','door','document'] else '',activityId=group,handlingMode='pallet' if kind in ['pallet','rack'] else 'loose-item' if kind=='pick' else 'context'))
    flows.append(dict(id=id,name=name,area=area,warehouseTypes=warehouse.split('|'),sourceId=sid,legacy=legacy,activities=activities,actions=actions,branches=branches or 'Repeat the work request until complete. A mismatch or equipment fault stops this path and returns to the assigned operator.',reviewStatus='Engineering draft · owner review required',basis='Activity names are read from the photo. Atomic actions and capability requirements are engineering inferences. Timing, frequency, load, geometry, and technology performance are not established.'))
